import { mapState } from "vuex";
import {
  outListApi,
  outStatusApi,
  outSaveApi,
  outSavesApi,
  interfaceList,
  setUpPush,
  textOutUrl,
} from "@/api/setting";
export default {
  name: "user_level",
  data() {
    return {
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24,
      },
      modalsid: "",
      loading: false,
      columns1: [
        {
          title: "ID",
          key: "id",
          width: 50,
        },
        {
          title: "账号",
          key: "appid",
          minWidth: 100,
        },
        {
          title: "描述",
          key: "title",
          minWidth: 120,
        },
        {
          title: "添加时间",
          key: "add_time",
          minWidth: 100,
        },
        {
          title: "最后登录时间",
          key: "last_time",
          minWidth: 100,
        },
        {
          title: "登录",
          key: "ip",
          minWidth: 100,
        },
        {
          title: "状态",
          slot: "status",
          minWidth: 120,
        },
        {
          title: "操作",
          slot: "action",
          fixed: "right",
          minWidth: 85,
        },
      ],
      formValidate: {
        name: "",
        status: "",
        page: 1,
        limit: 15,
      },
      modalsdate: {
        appid: "",
        appsecret: "",
        title: "",
        rules: [],
      },
      ruleValidate: {
        appid: [
          {
            required: true,
            message: "请输入正确的账号 (不少于8位数)",
            trigger: "blur",
            min: 8,
          },
        ],
        appsecret: [
          {
            required: true,
            message: "请输入正确的密码 (不少于32位数)",
            trigger: "blur",
            min: 32,
          },
        ],
      },
      levelLists: [],
      total: 0,
      modals: false,
      type: 0,
      intList: [],
      settingModals: false,
      settingData: {
        switch: 1,
        name: "",
      },
    };
  },
  created() {
    this.getList();
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  methods: {
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `setting/system_out/delete/${row.id}`,
        method: "DELETE",
        ids: "",
      };
      this.$modalSure(delfromData)
        .then((res) => {
          this.$Message.success(res.msg);
          this.levelLists.splice(num, 1);
          if (!this.levelLists.length) {
            this.formValidate.page =
              this.formValidate.page == 1 ? 1 : this.formValidate.page - 1;
          }
          this.getList();
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    // 修改是否显示
    onchangeIsShow(row) {
      outStatusApi(row.id, row.status)
        .then((res) => {
          this.$Message.success(res.msg);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    // 等级列表
    getList() {
      this.loading = true;
      outListApi(this.formValidate)
        .then((res) => {
          let data = res.data;
          this.levelLists = data.list;
          this.total = data.count;
          this.loading = false;
        })
        .catch((res) => {
          this.loading = false;
          this.$Message.error(res.msg);
        });
    },
    pageChange(index) {
      this.formValidate.page = index;
      this.getList();
    },
    // 添加
    add() {
      this.modals = true;
      this.type = 0;
      this.modalsdate = {
        appid: "",
        appsecret: "",
        title: "",
        rules: [],
      };
      this.getIntList();
    },
    // 编辑
    edit(row) {
      console.log(row);
      this.modals = true;
      this.modalsdate.appid = row.appid;
      this.modalsdate.title = row.title;
      this.modalsdate.appsecret = row.apppwd;
      this.modalsdate.rules = row.rules.map((e) => {
        return Number(e);
      });

      this.modalsid = row.id;
      console.log(this.modalsid);
      this.type = 1;
      this.getIntList("edit", this.modalsdate.rules);
    },
    getIntList(type, list) {
      interfaceList().then((res) => {
        this.intList = res.data;
        if (!type) {
          this.intList.map((item) => {
            if (item.id === 1) {
              item.checked = true;
              item.disableCheckbox = true;
              if (item.children.length) {
                item.children.map((v) => {
                  v.checked = true;
                  v.disableCheckbox = true;
                });
              }
            }
          });
        } else {
          list.map((item) => {
            this.intList.map((e) => {
              if (e.id === 1) {
                e.checked = true;
                e.disableCheckbox = true;
                if (e.children.length) {
                  e.children.map((v) => {
                    v.checked = true;
                    v.disableCheckbox = true;
                  });
                }
              }
              listData(e.children || [], item);
            });
          });
        }
        function listData(list, id) {
          if (list.length) {
            list.map((v) => {
              if (v.id == id) {
                v.checked = true;
              }
              if (v.children) {
                listData(v.children);
              }
            });
          }
        }
      });
    },
    ok(name) {
      this.$refs[name].validate((valid) => {
        if (valid) {
          this.modalsdate.rules = [];
          this.$refs.tree.getCheckedAndIndeterminateNodes().map((node) => {
            this.modalsdate.rules.push(node.id);
          });
          outSaveApi(this.modalsdate)
            .then((res) => {
              this.modalsdate = {
                appid: "",
                appsecret: "",
                title: "",
                rules: [],
              };
              (this.modals = false), this.$Message.success(res.msg);
              this.modalsid = "";
              this.getList();
            })
            .catch((err) => {
              this.$Message.error(err.msg);
            });
        } else {
          this.$Message.warning("请完善数据");
        }
      });
    },
    oks(name) {
      this.$refs[name].validate((valid) => {
        if (valid) {
          this.modalsdate.rules = [];
          this.$refs.tree.getCheckedAndIndeterminateNodes().map((node) => {
            this.modalsdate.rules.push(node.id);
          });
          outSavesApi(this.modalsid, this.modalsdate)
            .then((res) => {
              this.modalsdate = {
                appid: "",
                appsecret: "",
                title: "",
                rules: [],
              };
              (this.modals = false), this.$Message.success(res.msg);
              this.modalsid = "";
              this.getList();
            })
            .catch((err) => {
              this.$Message.error(err.msg);
            });
        } else {
          this.$Message.warning("请完善数据");
        }
      });
    },
    cancel() {
      this.modalsid = "";
      this.modalsdate = {
        appid: "",
        appsecret: "",
        title: "",
        rules: [],
      };
      this.modals = false;
    },
    setUp(row) {
      this.settingModals = true;
      this.settingData = row;
    },
    submit(name) {
      setUpPush(this.settingData).then((res) => {
        this.$Message.success(res.msg);
        this.settingModals = false;
        this.getList();
      });
    },
    textOutUrl() {
      textOutUrl(this.settingData)
        .then((res) => {
          this.$Message.success(res.msg);
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    },
    reset() {
      let len = 32;
      let chars = "ABCDEFGHJKMNPQRSTWXYZabcdefhijkmnprstwxyz2345678";
      let maxPos = chars.length;
      let pwd = "";
      for (let i = 0; i < len; i++) {
        pwd += chars.charAt(Math.floor(Math.random() * maxPos));
      }
      this.modalsdate.appsecret = pwd;
    },
    // 表格搜索
    userSearchs() {
      this.formValidate.page = 1;
      this.getList();
    },
  },
};
